import{_ as r,a0 as s,w as e,s as x,I as l,x as i,a1 as o,A as u,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"用於與非 Linux 用户一同工作的 Linux 命令列工具 | LCTT x X-CMD","titleTemplate":false,"description":"用於與非 Linux 用户一同工作的 Linux 命令列工具 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用於與非 Linux 用户一同工作的 Linux 命令列工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用於與非 Linux 用户一同工作的 Linux 命令列工具 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20171101 Linux command line tools for working with non-Linux users","title":"用於與非 Linux 用户一同工作的 Linux 命令列工具","tag":"201808","desc":""},"relativePath":"201808/20171101 Linux command line tools for working with non-Linux users.md","filePath":"[post].md"}'),d={name:"201808/20171101 Linux command line tools for working with non-Linux users.md"};function w(m,n,L,f,a,g){const t=s("Link");return e(),x("div",null,[n[23]||(n[23]=l("h1",{id:"用於與非-linux-用户一同工作的-linux-命令列工具",tabindex:"-1"},[i("用於與非 Linux 用户一同工作的 Linux 命令列工具 "),l("a",{class:"header-anchor",href:"#用於與非-linux-用户一同工作的-linux-命令列工具","aria-label":"Permalink to “用於與非 Linux 用户一同工作的 Linux 命令列工具”"},"​")],-1)),n[24]||(n[24]=l("blockquote",null,[l("p",null,"如果你在 Linux 終端工作，那麼與非 Linux 用户一同工作時可能遇到困難。這些工具有助於文檔兼容性和企業即時消息。")],-1)),n[25]||(n[25]=l("p",null,[l("img",{src:"https://images.techhive.com/images/article/2016/06/linux-shell-100666628-large.jpg",alt:""})],-1)),n[26]||(n[26]=l("p",null,"我大部分時間都在使用 Shell（命令列、終端或其它隨便什麼你使用的平台）上。但是，當我需要與大量其他人合作時，這可能會有點挑戰，特別是在大型企業公司中 —— 除了 shell 外其他都使用。",-1)),n[27]||(n[27]=l("p",null,"當公司內的其他人使用與你不同的平台時，問題就會變得更加嚴重。我傾向於使用 Linux。如果我在 Linux 終端上做了很多日常工作，而我的大多數同事都使用 Windows 10（完全使用 GUI 端），那麼事情就會變得……有問題。",-1)),l("ul",null,[l("li",null,[n[1]||(n[1]=l("strong",null,"Network World 上另外一篇文章：",-1)),o(t,{href:"http://www.networkworld.com/article/2926630/linux/11-pointless-but-awesome-linux-terminal-tricks.html#tk.nww-fsb"},{default:u(()=>[...n[0]||(n[0]=[l("strong",null,"11 個沒用但很酷的 Linux 終端技巧",-1)])]),_:1})])]),n[28]||(n[28]=l("p",null,"幸運的是，在過去的幾年裏，我已經想出如何處理這些問題。我已經找到了在非 Unix 的企業環境中使用 Linux（或其他類 Unix 系統）Shell 的方法。這些工具/技巧同樣適用於在公司服務器上工作的系統管理員們，就像對開發人員或營銷人員一樣。",-1)),n[29]||(n[29]=l("p",null,"讓我們首先關注對於大公司中的許多人來説似乎最難解決的兩個方面：文檔兼容性和企業即時消息。",-1)),n[30]||(n[30]=l("h3",{id:"linux-和非-linux-系統之間的文檔兼容性",tabindex:"-1"},[i("Linux 和非 Linux 系統之間的文檔兼容性 "),l("a",{class:"header-anchor",href:"#linux-和非-linux-系統之間的文檔兼容性","aria-label":"Permalink to “Linux 和非 Linux 系統之間的文檔兼容性”"},"​")],-1)),n[31]||(n[31]=l("p",null,"出現的最大問題之一是簡單的文字處理文檔的兼容性。",-1)),n[32]||(n[32]=l("p",null,"假設你的公司已在 Microsoft Office 上進行了標準化。這讓你難過。但不要失去希望！有很多方法可以使它（基本）可用 —— 甚至在 shell 中。",-1)),l("p",null,[n[4]||(n[4]=i("兩個工具在我的武器庫中至關重要：",-1)),o(t,{href:"https://www.youtube.com/watch?v=BkTYHChkDoE"},{default:u(()=>[...n[2]||(n[2]=[i("Pandoc",-1)])]),_:1}),n[5]||(n[5]=i(" 和 ",-1)),o(t,{href:"https://www.youtube.com/watch?v=WnMyamBgKFE"},{default:u(()=>[...n[3]||(n[3]=[i("Wordgrinder",-1)])]),_:1}),n[6]||(n[6]=i("。",-1))]),n[33]||(n[33]=p('<p>Wordgrinder 是一個簡單、直觀的文字處理器。它可能不像 LibreOffice 那樣功能齊全（或者，實際上，任何主要的 GUI 文字處理應用程序），但速度很快。它很穩定。它有足夠的功能（和文件格式）來完成工作。事實上，我完全在 Wordgrinder 中寫了我的大部分文章和書籍。</p><p>但是有一個問題（你知道肯定會有）。</p><p>Wordgrinder 不支持 .doc（或 .docx）文件。這意味着它無法讀取使用 Windows 和 MS Office 的同事發送給你的大多數文件。</p><p>這就是 Pandoc 的用武之地。它是一個簡單的文檔轉換器，可以將各種文件作為輸入（MS Word、LibreOffice、HTML、markdown 等）並將它們轉換為其他內容。它支持的格式數量絕對是驚人的 —— PDF、ePub、各種幻燈片格式。它確實使格式之間的文檔轉換變得輕而易舉。</p><p>這並不是説我不會偶爾遇到格式或功能問題。要轉換有大量自定義格式、某些腳本和嵌入式圖表的 Word 文檔？是的，在這個過程中會丟失很多。</p><p>但實際上，Pandoc（用於轉換文件）和 Wordgrinder（用於文檔編輯）的組合已經證明非常有用和強大。</p><h3 id="linux-和非-linux-系統之間的企業即時消息傳遞" tabindex="-1">Linux 和非 Linux 系統之間的企業即時消息傳遞 <a class="header-anchor" href="#linux-和非-linux-系統之間的企業即時消息傳遞" aria-label="Permalink to “Linux 和非 Linux 系統之間的企業即時消息傳遞”">​</a></h3><p>每家公司都喜歡在即時通訊系統上實現標準化 —— 所有員工都可以使用它來保持實時聯繫。</p><p>在命令列中，這可能會變得棘手。如果貴公司使用 Google 環聊怎麼辦？或者 Novell GroupWise Messenger 怎麼樣？既沒有官方支持，也沒有基於終端的客户端。</p>',9)),l("p",null,[n[8]||(n[8]=i("謝天謝地，還有 ",-1)),o(t,{href:"https://www.youtube.com/watch?v=19lbWnYOsTc"},{default:u(()=>[...n[7]||(n[7]=[i("Finch 和 Hangups",-1)])]),_:1}),n[9]||(n[9]=i("。",-1))]),n[34]||(n[34]=l("p",null,"Finch 是 Pidgin（開源，多協議消息客户端）的終端版本。它支持各種協議，包括 Novell GroupWise、（很快會死的）AOL Instant Messenger 以及其他一些協議。",-1)),n[35]||(n[35]=l("p",null,"而 Hangups 是 Google Hangouts 客户端的開源實現 —— 包含消息歷史記錄和精美的標籤界面。",-1)),n[36]||(n[36]=l("p",null,"這些方案都不會為你提供語音或視頻聊天功能，但對於基於文本的消息，它們的工作得非常好。它們並不完美（Finch 的用户界面需要時間習慣），但它們肯定足以與你的同事保持聯繫。",-1)),n[37]||(n[37]=l("p",null,"這些方案能否讓你在純文本 shell 中舒適地過完一個工作日？可能不會。就個人而言，我發現（使用這些工具和其他工具）我可以輕鬆地將 80％ 的時間花在純文本界面上。",-1)),n[38]||(n[38]=l("p",null,"這感覺很棒。",-1)),n[39]||(n[39]=l("hr",null,null,-1)),l("p",null,[n[11]||(n[11]=i("via: ",-1)),o(t,{href:"https://www.networkworld.com/article/3235688/linux/linux-command-line-tools-for-working-with-non-linux-users.html"},{default:u(()=>[...n[10]||(n[10]=[i("https://www.networkworld.com/article/3235688/linux/linux-command-line-tools-for-working-with-non-linux-users.html",-1)])]),_:1})]),l("p",null,[n[15]||(n[15]=i("作者：",-1)),o(t,{href:"https://www.networkworld.com/author/Bryan-Lunduke/"},{default:u(()=>[...n[12]||(n[12]=[i("Bryan Lunduke",-1)])]),_:1}),n[16]||(n[16]=i(" 譯者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:u(()=>[...n[13]||(n[13]=[i("geekpi",-1)])]),_:1}),n[17]||(n[17]=i(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:u(()=>[...n[14]||(n[14]=[i("wxy",-1)])]),_:1})]),l("p",null,[n[20]||(n[20]=i("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...n[18]||(n[18]=[i("LCTT",-1)])]),_:1}),n[21]||(n[21]=i(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:u(()=>[...n[19]||(n[19]=[i("Linux中國",-1)])]),_:1}),n[22]||(n[22]=i(" 榮譽推出",-1))])])}const C=r(d,[["render",w]]);export{b as __pageData,C as default};
